<script setup lang="ts">
const api=useApi(); const { data: partners, refresh }=await useAsyncData('admin-partners',()=>api.request<any[]>('/admin/manufacturers').catch(()=>[]))
async function approve(id:string){await api.request(`/admin/manufacturers/${id}/approve`,{method:'POST'});await refresh()}
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">Supply network</p><h1 class="mt-1 font-display text-[clamp(2.2rem,3vw,2.7rem)] font-semibold tracking-[-.045em]">Partners.</h1><p class="mt-1 text-[11.5px] text-ink/45">Manufacturer subscriptions and listing status.</p></div><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><div v-for="p in partners" :key="p._id" class="a-card p-5"><div class="flex items-start justify-between"><div><p class="font-display text-[20px]">{{ p.name }}</p><p class="font-mono text-[8px] text-ink/30">{{ p.country }} · {{ p.plan }}</p></div><StatusPill :status="p.status"/></div><div class="mt-5 grid grid-cols-2 gap-2 border-t border-ink/10 pt-3"><div><p class="font-mono text-[7px] uppercase text-ink/30">Monthly fee</p><p class="text-[13px]">{{ money(p.monthlyFee) }}</p></div><div><p class="font-mono text-[7px] uppercase text-ink/30">Listings</p><p class="text-[13px]">{{ p.listings }}</p></div></div><p class="mt-3 text-[10px] text-ink/40">{{ p.contact }}</p><button v-if="p.status!=='verified'" class="mt-3 font-mono text-[8px] uppercase text-signal-deep" @click="approve(p._id)">Approve partner →</button></div></div></div></template>
